    }
    buckets {
      edges {
        node {
          id
          name
        }
      }
    }
    environments {
      edges {
        node {
          id
          name
          canAccess
          deletedAt
          unmergedChangesCount
        }
      }
    }
    services {
      edges {
        node {
          id
          name
        }
      }
    }
  }
}
","variables":{"id":"project-1"}}

